 const valid=['sunny','rain','snow','thunder','crystal','hell'];const next=until>Date.now()&&valid.includes(row.weather_type)?{type:row.weather_type,types:[row.weather_type,...(valid.includes(row.weather_type_2)&&row.weather_type_2!==row.weather_type?[row.weather_type_2]:[])],until,by:row.summoned_by||'玩家',at:row.updated_at?new Date(row.updated_at).getTime():Date.now()}:null;
