const DEVICE_ACCOUNT_LIMIT=3;
function taipeiDayKey(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const v={};for(const p of parts)v[p.type]=p.value;return `${v.year}-${v.month}-${v.day}`;}
