function checkAndRecordDeviceAccount(email){const normalized=String(email||'').trim().toLowerCase();if(!normalized)return {allowed:true};const ledger=getDeviceAccountLedger();const exists=ledger.accounts.some(x=>String(x).toLowerCase()===normalized);if(!exists&&ledger.accounts.length>=DEVICE_ACCOUNT_LIMIT)return {allowed:false,remaining:0};if(!exists)ledger.accounts.push(normalized);localStorage.setItem('diceRealmDeviceAccountLimitV1',JSON.stringify(ledger));return {allowed:true,remaining:Math.max(0,DEVICE_ACCOUNT_LIMIT-ledger.accounts.length)};}
