function petBonusTotals(){const rarityBonus={common:{luck:1,speed:0},rare:{luck:1,speed:1},legendary:{luck:2,speed:1},mythic:{luck:3,speed:3},secret:{luck:7,speed:7}};const mutationMultiplier={rain:1.2,snow:1.3,thunder:1.4,crystal:1.7,hell:2};let luck=0,speed=0;const owned=Array.isArray(S.pets)?S.pets:[],equipped=new Set(Array.isArray(S.equippedPetUids)?S.equippedPetUids:[]);for(const item of owned){if(!equipped.has(item.uid))continue;const p=petById(item.id),b=rarityBonus[p?.rarity];if(b){const m=(mutationMultiplier[item.mutation]||1)*petWeightSkillMultiplier(item.kg);luck+=b.luck*m;speed+=b.speed*m}}return {luck,speed}}
