// 天堂藥水 I 專屬固定機率。加入天氣限定骰子後，會從原本大於 10% 的項目分配機率，總和仍為 100%。
const ANGEL_ODDS=[
 ['d11',33],['d28',28],['d12',16],['d13',9.9],['d14',5.99],['d15',3.5],
 ['d16',1.8],['d17',0.9],['d18',0.45],['d19',0.2],['d29',0.1],['d30',0.01],
 ['d20',0.08],['d21',0.04],['d22',0.015],['d23',0.008],['d25',0.004],
 ['d26',0.0015],['d31',0.0007],['d24',0.0005],['d27',0.0002],['d32',0.0001]
];
// 當前天氣中，每顆分母 > 2048 的限定骰子各獲得 1% 機率。
// 這些機率從原本大於 10% 的項目按比例扣除，不會讓總機率超過 100%。
function addWeatherOdds(entries,pool,weather){
 const baseTotal=entries.reduce((sum,x)=>sum+x.weight,0);
 if(baseTotal>0)entries.forEach(x=>x.weight=x.weight/baseTotal*100);
 const weatherDice=pool.filter(d=>d.weather===weather&&Number(d.den)>2048);
 if(!weatherDice.length)return entries;
 const donors=entries.filter(x=>x.weight>10);
 const donorTotal=donors.reduce((sum,x)=>sum+x.weight,0);
 const reserve=weatherDice.length;
 if(donorTotal<=reserve)return entries;
 donors.forEach(x=>x.weight-=reserve*(x.weight/donorTotal));
 weatherDice.forEach(d=>entries.push({dice:d,weight:1}));
 return entries;
}
function isHalloweenDice(d){return ['d33','d34','d35','d36'].includes(d?.id)}
function halloweenDiceUnavailable(){const now=new Date();return now.getFullYear()>2026||(now.getFullYear()===2026&&(now.getMonth()>10||(now.getMonth()===10&&now.getDate()>=1)));}
function weightedRoll(){
 const angel=(Number(S.potions?.angelCharges)||0)>0;
 const heaven2=(S.potions?.angelMode==='angel2');
 const weatherState=getWeather(),weather=weatherState.type||'sunny',weatherTypes=weatherState.types||[weather];
 const pool=D.filter(d=>(!d.weather||weatherTypes.includes(d.weather))&&(!isHalloweenDice(d)||!halloweenDiceUnavailable()));
 if(heaven2){
  // 天堂藥水 II 內部機率表；不在玩家介面公開。由較常見到較稀有逐步遞減，總和精確為 100%。
  const heaven2Odds={d14:20,d34:10.1218,d15:8.6757,d16:7.7118,d29:6.7478,d17:6.2658,d35:5.7838,d18:5.3018,d19:4.8198,d30:5.045,d20:4.563,d21:4.081,d22:3.599,d23:2.4099,d25:1.9279,d26:1.4459,d31:0.5,d24:0.5,d27:0.495,d32:0.005};
  let entries=D.filter(d=>Object.prototype.hasOwnProperty.call(heaven2Odds,d.id)&&(!d.weather||d.weather===weather)&&(!isHalloweenDice(d)||!halloweenDiceUnavailable())).map(d=>({dice:d,weight:heaven2Odds[d.id]*(weather==='hell'&&d.den>=700000?1/0.95:1)}));
  entries=addWeatherOdds(entries,pool,weather);
  const total=entries.reduce((sum,x)=>sum+x.weight,0);
  let r=Math.random()*total;
  for(const entry of entries){r-=entry.weight;if(r<0)return entry.dice;}
  return entries[entries.length-1]?.dice||byId('d14');
 }
 if(angel){
  let entries=ANGEL_ODDS.map(([id,percent])=>({dice:byId(id),weight:percent*(weather==='hell'&&byId(id)?.den>=700000?1/0.95:1)})).filter(x=>x.dice&&(!x.dice.weather||x.dice.weather===weather)&&(!isHalloweenDice(x.dice)||!halloweenDiceUnavailable()));
  entries=addWeatherOdds(entries,pool,weather);
  const total=entries.reduce((sum,x)=>sum+x.weight,0);
  let r=Math.random()*total;
  for(const entry of entries){r-=entry.weight;if(r<0)return entry.dice;}
  return entries[entries.length-1].dice;
 }
 // 一般擲骰沿用原本的分級運氣權重。
 const tenthRoll=(Number(S.rolls)||0)%10===0;
 const currentLuck=Math.max(0,Number(luck())||0);
 const effective=Math.max(0,Math.min(200,currentLuck+(tenthRoll?100:0)));
 const weights=pool.map(d=>{
  let factor;
  if(d.den<=1024) factor=1-effective*0.003;
  else if(d.den<=32768) factor=1+effective*0.006;
  else if(d.den<=1048576) factor=1+effective*0.0015;
  else factor=1+effective*0.0005;
  const rollDen=weather==='hell'&&d.den>=700000?d.den*0.95:d.den;
  return (1/Math.max(2,rollDen))*Math.max(0.1,factor);
 });
 const total=weights.reduce((a,b)=>a+b,0);let r=Math.random()*total;
 for(let i=0;i<pool.length;i++){r-=weights[i];if(r<=0)return pool[i]}
 return pool[0];
}
