function populateAdminPetSelects(){const options=PETS.map(p=>`<option value="${p.id}">${p.name}（${petRarity(p.rarity).name}）</option>`).join('');for(const id of ['adminSinglePetId','adminAllPetId']){const el=document.getElementById(id);if(el&&!el.options.length)el.innerHTML=options}} function petById(id){return PETS.find(p=>p.id===id)}
