function petTierFromDen(den){if(den<=1000)return 1;if(den<=3000)return 2;if(den<=5000)return 3;if(den<=10000)return 4;if(den<=40000)return 5;if(den<=150000)return 6;if(den<=550000)return 7;if(den<=1100000)return 8;if(den<=10000000)return 9;if(den<=45000000)return 10;return 11}
