function renderPetChance(tier){const rows=document.getElementById('petChanceRows'),bar=document.getElementById('petChanceBar');if(bar)bar.innerHTML='';if(!tier){rows.innerHTML='<div class="empty">放入兩顆相同骰子後顯示機率。</div>';return}const rates=PET_TIER_RATES[tier]||PET_TIER_RATES[1];rows.innerHTML=PET_RARITIES.map(r=>{const value=rates[r.id]||0;return `<div class="pet-prob-row" style="display:grid;grid-template-columns:64px minmax(0,1fr) 48px;align-items:center;gap:10px;padding:8px 2px;border-bottom:1px solid #ffffff12"><b class="${r.cls}" style="background:linear-gradient(90deg,${r.a},${r.b});-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:0 0 10px ${r.a}33">${r.name}</b><div class="pet-prob-track" aria-label="${r.name} ${value}%" style="background:linear-gradient(90deg,#171c30,#252b43)"><span style="width:${Math.max(0,Math.min(100,value))}%;--prob-a:${r.a};--prob-b:${r.b};background:linear-gradient(90deg,${r.a},${r.b});box-shadow:0 0 8px ${r.a}66"></span></div><strong style="text-align:right">${value}%</strong></div>`}).join('')}
function refreshPetDiceSelects(){const a=document.getElementById('petDiceSlotA'),b=document.getElementById('petDiceSlotB');if(!a||!b)return;const all=D.filter(d=>(Number(S.bag[d.id])||0)>=1).sort((x,y)=>x.den-y.den);const oldA=a.value,oldB=b.value;let optsA=all,optsB=all;if(oldA){optsB=all.filter(d=>d.id===oldA&&(Number(S.bag[d.id])||0)>=2)}else if(oldB){optsA=all.filter(d=>d.id===oldB&&(Number(S.bag[d.id])||0)>=2)}const make=(items,placeholder)=>'<option value="">'+placeholder+'</option>'+items.map(d=>`<option value="${d.id}">${d.name}（1/${d.den.toLocaleString('en-US')}）×${S.bag[d.id]}</option>`).join('');a.innerHTML=make(optsA,'選擇骰子');b.innerHTML=make(optsB,'選擇骰子');if(optsA.some(d=>d.id===oldA))a.value=oldA;if(optsB.some(d=>d.id===oldB))b.value=oldB;}
function renderPetsPage(){if(!document.getElementById('page-pets'))return;S.pets=Array.isArray(S.pets)?S.pets:[];ensurePetData(S.pets);S.equippedPetUids=Array.isArray(S.equippedPetUids)?S.equippedPetUids.filter(uid=>S.pets.some(p=>p.uid===uid)).slice(0,3):[];document.getElementById('petOwnedCount').textContent='持有 '+S.pets.length+' / 20 隻寵物';document.getElementById('petInventoryCount').textContent=S.pets.length+' / 20 隻 · 已裝備 '+S.equippedPetUids.length+'/3';const rarityOrder={common:0,rare:1,legendary:2,mythic:3,secret:4};const sortedPets=[...S.pets].sort((a,b)=>(rarityOrder[petById(a.id)?.rarity]??99)-(rarityOrder[petById(b.id)?.rarity]??99));document.getElementById('petInventoryGrid').innerHTML=sortedPets.map(x=>{const p=petById(x.id),r=petRarity(p?.rarity),equipped=S.equippedPetUids.includes(x.uid);return `<div class="pet-card ${equipped?'pet-equipped':''}" style="border-color:${equipped?'#7d8cff':'#ffffff20'}"><div class="pet-art">${petArt(p,true)}</div><div class="pet-name ${r.cls}">${p?.name||'未知'}</div><div class="pet-meta ${r.cls}">${r.name} · ${Number.isFinite(Number(x.kg))?Number(x.kg).toLocaleString('en-US')+' kg':'重量未知'}${petMutationLabel(x)?' · <span style="color:'+(PET_MUTATIONS[x.mutation]?.color||'#fff')+'">'+petMutationLabel(x)+'</span>':''}</div>${(SECRET_PET_SKILLS[x.id]||MYTHIC_PET_SKILLS[x.id])?`<div class="mini" style="margin-top:5px;color:#c7d2fe">技能：${(SECRET_PET_SKILLS[x.id]||MYTHIC_PET_SKILLS[x.id]).skill}</div>`:''}<button type="button" class="${equipped?'primary':'quiet'}" data-pet-equip="${escapeHTML(x.uid)}" style="width:100%;margin-top:8px">${equipped?'✓ 已裝備 · 點擊卸下':'裝備寵物'}</button></div>`}).join('')||'<div class="empty" style="grid-column:1/-1">尚未擁有寵物，先使用兩顆骰子合成。</div>';const a=document.getElementById('petDiceSlotA'),b=document.getElementById('petDiceSlotB');refreshPetDiceSelects();updatePetDicePreview();}
