function renderCodex(){
 if(codexCategory==='pets'){renderPetCodex();return}
 document.getElementById('codexGrid').className='';
 if(codexCategory==='weather'&&Date.now()-weatherDiceExistLoadedAt>60000)loadWeatherDiceExistCounts();
 const isHalloweenCategory=codexCategory==='halloween';
 const allDice=[...D].filter(d=>isHalloweenCategory?['d33','d34','d35','d36'].includes(d.id):codexCategory==='weather'?!!d.weather:!d.weather&&!['d33','d34','d35','d36'].includes(d.id)).sort((a,b)=>{if(codexCategory==='weather'){const order={rain:0,snow:1,thunder:2,crystal:3,hell:4};return (order[a.weather]??9)-(order[b.weather]??9)||a.den-b.den;}return a.den-b.den;});
 const discoveredCount=allDice.filter(d=>!!S.first[d.id]||!!S.bag[d.id]).length;
 const pct=Math.round(discoveredCount/Math.max(1,allDice.length)*100);
 document.getElementById('codexPct').textContent=pct+'% · 已發現 '+discoveredCount+'/'+allDice.length;
 document.getElementById('codexBar').style.width=pct+'%';
 document.querySelectorAll('[data-codex-category]').forEach(b=>b.classList.toggle('active',b.dataset.codexCategory===codexCategory));
 document.getElementById('codexGrid').innerHTML=allDice.map(d=>{
  const discovered=!!S.first[d.id]||!!S.bag[d.id],rolls=Number(S.rollCounts?.[d.id])||0;
  const isHalloween=['d33','d34','d35','d36'].includes(d.id);
  const codexColor=isHalloween?'#ff8a3d':d.weather?({rain:'#75baff',snow:'#f4fbff',thunder:'#fff000',crystal:'#ed75ff',hell:'#ff6038'}[d.weather]||'#9b9aff'):'#9b9aff';
  const exist=d.weather?Number(weatherDiceExistCounts[d.id])||0:null;return `<div class="codex-entry"><div class="codex-row ${discovered?'':'missing'} ${isHalloween?'codex-halloween':d.weather?'codex-weather-'+d.weather:'codex-standard'}" style="--rarity-color:${codexColor}"><div class="codex-chance">${discovered?chanceText(d):'???'}</div><div class="codex-name"><span class="codex-icon" style="color:${discovered?codexColor:'#525873'}">${discovered?d.icon:'???'}</span>${discovered?d.name:'???'}</div><div class="codex-count">${d.weather?`抽到 ${format(rolls)} 次 · exist: ${exist===null?'…':format(exist)}`:discovered?(rolls?`抽到 ${format(rolls)} 次`:'已獲得'):'???'}</div></div></div>`;
 }).join('');
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-codex-category]');if(!b)return;codexCategory=b.dataset.codexCategory;if(codexCategory!=='pets'){document.querySelector('#page-codex .hero .eyebrow').textContent='ARCHIVE DATABASE';document.querySelector('#page-codex .hero h1').textContent='記錄每一次奇蹟。';document.querySelector('#page-codex .hero .muted').textContent='未發現的骰子將以未知檔案顯示。部分高階骰子擁有專屬視覺。';document.getElementById('codexGrid').className='codex-list'}renderCodex()});
function canCraft(g){return g.recipe.every(([id,n])=>(S.bag[id]||0)>=n)}
function renderGloves(){let g=currentGlove();document.getElementById('gloveLabel').textContent=g.name;document.getElementById('equippedName').textContent=g.icon+' '+g.name;document.getElementById('equippedDesc').textContent=g.desc;document.getElementById('gloveLuck').textContent='+'+g.luck+'%';document.getElementById('gloveSpeed').textContent='+'+g.speed+'%';document.getElementById('gloveOwned').textContent=Object.keys(S.gloves||{}).filter(id=>S.gloves[id]>0).length;const convertPanel=document.getElementById('weatherConvertPanel'),convertBtn=document.getElementById('weatherConvertBtn'),convertCooldown=document.getElementById('weatherConvertCooldown');if(convertPanel){const canConvert=S.equipped==='g7'&&!!S.gloves?.g7;convertPanel.hidden=!canConvert;if(canConvert){const left=Math.max(0,60*60*1000-(Date.now()-(Number(S.weatherConvertAt)||0)));convertBtn.disabled=left>0;convertBtn.textContent=left>0?'⏳ 天氣轉換冷卻中':'🌦️ 轉換全服天氣';convertCooldown.textContent=left>0?'剩餘冷卻 '+String(Math.floor(left/3600000)).padStart(2,'0')+':'+String(Math.floor(left%3600000/60000)).padStart(2,'0')+':'+String(Math.floor(left%60000/1000)).padStart(2,'0'):'能力已就緒';}}
 document.getElementById('recipeList').innerHTML=G.filter(x=>x.id!=='g0').sort((a,b)=>a.luck-b.luck||a.speed-b.speed).map(x=>{let owned=!!S.gloves[x.id],equipped=S.equipped===x.id;return `<div class="recipe"><div style="flex:1;min-width:0"><h3>${x.icon} ${x.name}${equipped?'（已裝備）':owned?'（已持有）':''}</h3>${x.recipe.map(([id,n])=>{let have=S.bag[id]||0,ok=have>=n;return `<p style="color:${ok?'#65e6b2':'#ff829d'}">${ok?'✓':'缺少'} ${byId(id).name.replace(/骰子/g,'')}（${chanceText(byId(id))}）×${n}：持有 ${format(have)}</p>`}).join('')}<p>運氣 +${x.luck}% · 速度 +${x.speed}%</p></div><button ${owned?(equipped?'disabled':''):(canCraft(x)?'':'disabled')} data-craft="${x.id}">${equipped?'已裝備':owned?'裝備':'合成'}</button></div>`}).join('');
}
function craft(id){let g=glove(id);if(S.gloves[id]){S.equipped=id;save();render();toast('已裝備'+g.name+'（同時只能裝備一副手套）');return}if(!canCraft(g)){toast('材料不足');return}g.recipe.forEach(([did,n])=>{S.bag[did]-=n;if(S.bag[did]<=0)delete S.bag[did]});S.gloves[id]=1;S.equipped=id;S.quest.craft++;checkAchievements();save();if(currentUser)logCraft('glove',id,g.name);render();toast('合成成功並裝備：'+g.name)}
document.addEventListener('click',e=>{let c=e.target.closest('[data-craft]'),eq=e.target.closest('[data-equip]');if(c)craft(c.dataset.craft);if(eq){S.equipped=eq.dataset.equip;save();render();toast('已裝備'+glove(S.equipped).name)}});
function potionMaterialTotal(){return Object.values(S.potions?.materials||{}).reduce((sum,n)=>sum+Math.max(0,Number(n)||0),0)}
function renderPotionAutoAddChoices(){S.potions=S.potions||fresh().potions;S.potions.materials=S.potions.materials||{};{let left=4;for(const id of Object.keys(S.potions.materials)){const n=Math.max(0,Number(S.potions.materials[id])||0),keep=Math.min(n,left);if(keep)S.potions.materials[id]=keep;else delete S.potions.materials[id];left-=keep;}}S.potions.autoAddPotions=Array.isArray(S.potions.autoAddPotions)?S.potions.autoAddPotions.slice(0,2):[];S.potions.autoAdd=S.potions.autoAddPotions.length>0;}
function potionIngredientInfo(did,n){if(String(did).startsWith('potion:')){const pid=did.slice(7),p=POTIONS.find(x=>x.id===pid);return {name:p?.name||pid,icon:p?.icon||'🧪',odds:'藥水',have:Number(S.potions.inventory?.[pid])||0,need:n,isPotion:true,pid}}const d=byId(did);return {name:d?.name||did,icon:d?.icon||'🎲',odds:d?chanceText(d):'',have:(Number(S.bag[did])||0)+(Number(S.potions.materials?.[did])||0),need:n,isPotion:false,did,d}};
function renderPotions(){
 const potionList=document.getElementById('potionList');renderPotionAutoAddChoices();
 const a=activePotion('luck'),sp=activePotion('speed');document.getElementById('potionLuckNow').textContent='+'+luck()+'%';document.getElementById('potionSpeedNow').textContent='+'+speed()+'%';
 const remaining=[];if(a)remaining.push(`${a.name}：${Math.ceil(Math.max(0,Number(S.potions.active.expiresAt)-Date.now())/1000)} 秒`);if(sp)remaining.push(`${sp.name}：${Math.ceil(Math.max(0,Number(S.potions.activeSpeed.expiresAt)-Date.now())/1000)} 秒`);document.getElementById('potionTimer').textContent=remaining.join(' · ')||'未啟用';
 const statuses=[];if(a)statuses.push(`${a.name}：運氣 +${a.luck||0}%`);if(sp)statuses.push(`${sp.name}：擲骰速度 +${sp.speed||0}%`);if(S.potions.angelCharges>0)statuses.push(S.potions.angelMode==='angel2'?'天堂藥水 II 已準備好，下一抽機率已提升。':'天堂藥水 I 已準備好，下一抽可使用。');document.getElementById('potionStatus').textContent=statuses.join('｜')||'目前沒有生效中的藥水。';
 potionList.innerHTML=POTIONS.map(p=>{const count=Number(S.potions.inventory[p.id])||0,active=(p.speed?sp:a)?.id===p.id,autoSelected=(S.potions.autoAddPotions||[]).includes(p.id);const mats=p.recipe.map(([did,n])=>{const m=potionIngredientInfo(did,n),ok=m.have>=n;return `<div class="potion-material-line" style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center;padding:8px 10px;border:1px solid ${ok?'#286b57':'#543247'};border-radius:9px;background:${ok?'#102c27':'#211622'};margin:5px 0"><div style="min-width:0"><b>${m.icon} ${m.name}</b><div class="mini" style="margin-top:3px">${m.odds==='藥水'?'藥水材料':m.odds} · 需要 ×${n} · 持有 ${format(m.have)}</div></div><strong style="color:${ok?'#65e6b2':'#ff829d'};white-space:nowrap">${ok?'✓ 足夠':'✕ 缺少 '+format(n-m.have)}</strong></div>`}).join('');const can=Number(S.coins)>=p.cost&&p.recipe.every(([did,n])=>potionIngredientInfo(did,n).have>=n);return `<div class="potion-card" data-potion-card="${p.id}"><span class="potion-card-icon">${p.icon}</span><div class="potion-summary-main" style="cursor:default"><b>${p.name}</b><small style="display:block;color:var(--muted);font-size:12px;margin-top:3px">${p.desc}</small><span class="potion-owned">持有 ×${count}${active?' · 生效中':''}</span><div class="mini" style="margin-top:5px">合成費用：${format(p.cost)}€</div></div><div class="potion-action-buttons"><button data-craft-potion="${p.id}" ${can?'':'disabled'}>合成</button><button class="primary" data-use-potion="${p.id}" ${count<1?'disabled':''}>使用</button><button class="potion-auto-add ${autoSelected?'active':''}" data-toggle-auto-add="${p.id}">${autoSelected?'✓ 自動添加中':'自動添加'}</button></div><div class="potion-row-recipe" style="display:block;flex-basis:100%;width:100%"><div class="potion-recipe-list">${mats}<div class="mini" style="margin-top:7px">合成費用：${format(p.cost)}€</div></div></div></div>`}).join('');
}
function craftPotion(id){const p=POTIONS.find(x=>x.id===id);if(!p)return;S.potions=S.potions||fresh().potions;S.potions.materials=S.potions.materials||{};if(Number(S.coins)<p.cost){toast('€ 不足');return}for(const [did,n] of p.recipe){if(potionIngredientInfo(did,n).have<n){toast('材料不足');return}}S.coins-=p.cost;for(const [did,n] of p.recipe){if(String(did).startsWith('potion:')){const pid=did.slice(7);S.potions.inventory[pid]=Math.max(0,(Number(S.potions.inventory[pid])||0)-n);continue}let need=n,stash=Number(S.potions.materials[did])||0,take=Math.min(stash,need);if(take){S.potions.materials[did]=stash-take;need-=take}if(!S.potions.materials[did])delete S.potions.materials[did];if(need){S.bag[did]=(Number(S.bag[did])||0)-need;if(S.bag[did]<=0)delete S.bag[did]}}S.potions.inventory[id]=(Number(S.potions.inventory[id])||0)+1;if(currentUser){logCraft('potion',id,p.name);logPotionAction(id,p.name,'craft',{cost:p.cost,recipe:p.recipe});}S.quest=S.quest||{rolls:0,rare:0,craft:0};S.quest.craft=(Number(S.quest.craft)||0)+1;checkAchievements();save();render();toast('合成成功：'+p.name)}
function usePotion(id){const p=POTIONS.find(x=>x.id===id);if(!p)return;S.potions=S.potions||fresh().potions;S.potions.inventory=S.potions.inventory||{};S.potions.activeSpeed=S.potions.activeSpeed||{type:'',expiresAt:0};const count=Number(S.potions.inventory[id])||0;if(count<1){toast('沒有這瓶藥水');return}if(id==='angel1'||id==='angel2'){S.potions.inventory[id]=count-1;S.potions.angelCharges=(Number(S.potions.angelCharges)||0)+1;S.potions.angelMode=id;if(currentUser)logPotionAction(id,p.name,'use',{mode:'next_roll',charges:S.potions.angelCharges});save();render();toast(id==='angel2'?'天堂藥水 II 已準備好：更大幅度提升下一抽的機率':'天堂藥水 I 已準備好：大幅提升下一抽的機率');return}const slot=p.speed?'activeSpeed':'active',current=activePotion(p.speed?'speed':'luck'),stored=S.potions[slot]||{type:'',expiresAt:0};let nextExpiry=Date.now()+p.duration;if(current&&stored.type===id){nextExpiry=Math.max(Date.now(),Number(stored.expiresAt)||0)+p.duration}else if(current&&stored.type!==id){if(!confirm(`目前的${current.name}仍在生效。使用${p.name}會取代同類藥水效果與剩餘時間，另一類藥水不受影響。確定要更換嗎？`))return}S.potions.inventory[id]=count-1;S.potions[slot]={type:id,expiresAt:nextExpiry};if(currentUser)logPotionAction(id,p.name,'use',{expiresAt:new Date(nextExpiry).toISOString(),slot});if(autoTimer)restartAutoInterval();save();render();toast(current&&current.id===id?`${p.name}時間已延長，剩餘 ${Math.ceil((nextExpiry-Date.now())/1000)} 秒`:`${p.name}已生效 5 分鐘`)}
document.addEventListener('change',e=>{const box=e.target.closest('[data-auto-add-potion]');if(!box)return;S.potions=S.potions||fresh().potions;S.potions.autoAddPotions=Array.isArray(S.potions.autoAddPotions)?S.potions.autoAddPotions:[];const id=box.dataset.autoAddPotion;if(box.checked){if(S.potions.autoAddPotions.length>=2){box.checked=false;toast('自動添加最多只能選擇 2 種藥水');return}if(!S.potions.autoAddPotions.includes(id))S.potions.autoAddPotions.push(id)}else S.potions.autoAddPotions=S.potions.autoAddPotions.filter(x=>x!==id);S.potions.autoAdd=S.potions.autoAddPotions.length>0;save();renderPotions()});
document.addEventListener('click',e=>{const c=e.target.closest('[data-craft-potion]'),u=e.target.closest('[data-use-potion]'),toggle=e.target.closest('[data-toggle-auto-add]');if(toggle){S.potions=S.potions||fresh().potions;const id=toggle.dataset.toggleAutoAdd;S.potions.autoAddPotions=Array.isArray(S.potions.autoAddPotions)?S.potions.autoAddPotions:[];if(S.potions.autoAddPotions.includes(id))S.potions.autoAddPotions=S.potions.autoAddPotions.filter(x=>x!==id);else if(S.potions.autoAddPotions.length<2)S.potions.autoAddPotions.push(id);else{toast('自動添加最多只能選擇 2 種藥水');return}S.potions.autoAdd=S.potions.autoAddPotions.length>0;save();renderPotions();return}if(c)craftPotion(c.dataset.craftPotion);if(u)usePotion(u.dataset.usePotion)});
function grantAchievementReward(reward){if(!reward)return;if(reward.type==='coins')S.coins=(Number(S.coins)||0)+reward.amount;else if(reward.type==='potion'){S.potions=S.potions||fresh().potions;S.potions.inventory=S.potions.inventory||{};S.potions.inventory[reward.id]=(Number(S.potions.inventory[reward.id])||0)+reward.amount}}
function rewardText(reward){return reward.type==='coins'?format(reward.amount)+'€':(POTIONS.find(p=>p.id===reward.id)?.name||reward.id)+' ×'+reward.amount}
let achievementPopupQueue=[],achievementPopupOpen=false;
function showAchievementPopup(item){achievementPopupQueue.push(item);if(!achievementPopupOpen)showNextAchievementPopup()}
function showNextAchievementPopup(){const item=achievementPopupQueue.shift();if(!item){achievementPopupOpen=false;return}achievementPopupOpen=true;const overlay=document.getElementById('achievementPopOverlay');if(!overlay){toast('成就完成：'+item.name+'，獲得 '+item.reward);achievementPopupOpen=false;return}document.getElementById('achievementPopTitle').textContent='成就完成！'+item.name;document.getElementById('achievementPopDesc').textContent=item.desc+' · 完成時間：'+new Date(item.unlockedAt).toLocaleString();document.getElementById('achievementPopReward').textContent=item.reward;overlay.hidden=false}
function closeAchievementPopup(){const overlay=document.getElementById('achievementPopOverlay');if(overlay)overlay.hidden=true;achievementPopupOpen=false;if(achievementPopupQueue.length)setTimeout(showNextAchievementPopup,120)}
function checkAchievements(){S.achievements=S.achievements||{};if(!S.achievements.collect28&&S.achievements.collect30){S.achievements.collect28=S.achievements.collect30;S.achievements.collect28.name='收藏專家';S.achievements.collect28.desc='發現 28 種骰子';delete S.achievements.collect30;}const checks=[
 ['roll100','擲骰新手',S.rolls>=100,'累計擲骰 100 次',{type:'coins',amount:100}],
 ['roll1000','命運常客',S.rolls>=1000,'累計擲骰 1,000 次',{type:'coins',amount:1000}],
 ['roll10000','擲骰熟手',S.rolls>=10000,'累計擲骰 10,000 次',{type:'potion',id:'luck2',amount:2}],
 ['roll100000','命運征服者',S.rolls>=100000,'累計擲骰 100,000 次',{type:'potion',id:'angel1',amount:1}],
 ['roll200000','別再掛了',S.rolls>=200000,'累計擲骰 200,000 次',{type:'potion',id:'angel1',amount:1}],
 ['roll400000','不見天日',S.rolls>=400000,'累計擲骰 400,000 次',{type:'potion',id:'angel2',amount:1}],
 ['collect5','收藏起步',totalUnique()>=5,'發現 5 種骰子',{type:'coins',amount:500}],
 ['daily20','每日任務達人',Number(S.dailyQuestCompletions||0)>=20,'累計完成 20 次每日任務',{type:'coins',amount:50000}],
 ['collect12','收藏家',totalUnique()>=12,'發現 12 種骰子',{type:'coins',amount:1200}],
 ['collect20','收藏大師',totalUnique()>=20,'發現 20 種骰子',{type:'potion',id:'luck3',amount:1}],
 ['collect28','收藏專家',totalUnique()>=28,'發現 28 種骰子',{type:'potion',id:'luck3',amount:2}],
 ['rare2048','稀有發現者',!!S.best&&S.best.den>=2048,'獲得 1/2,048 或更稀有的骰子',{type:'potion',id:'luck2',amount:1}],
 ['rare1m','百萬分之一',!!S.best&&S.best.den>=1000000,'獲得 1/1M 或更稀有的骰子',{type:'potion',id:'luck3',amount:1}],
 ['rare10m','千萬分之一',!!S.best&&S.best.den>=10000000,'獲得 1/10M 或更稀有的骰子',{type:'potion',id:'luck3',amount:1}],
 ['craftVoid', '虛空',Number(S.gloves?.g3)>0,'合成虛空手套',{type:'potion',id:'speed1',amount:1}],
 ['craftUniverse','宇宙',Number(S.gloves?.g4)>0,'合成宇宙手套',{type:'potion',id:'speed2',amount:2}],
 ['rainCollect2','雨中收藏家',D.filter(d=>d.weather==='rain'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length>=2,'獲得兩種雨天骰子',{type:'coins',amount:8000}],
 ['snowCollect2','雪境收藏家',D.filter(d=>d.weather==='snow'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length>=2,'獲得兩種雪天骰子',{type:'potion',id:'luck3',amount:1}],
 ['thunderCollect2','雷霆收藏家',D.filter(d=>d.weather==='thunder'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length>=2,'獲得兩種打雷骰子',{type:'potion',id:'angel1',amount:1}],
 ['crystalCollect2','水晶收藏家',D.filter(d=>d.weather==='crystal'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length>=2,'獲得兩種水晶骰子',{type:'potion',id:'luck3',amount:1}],
 ['hellCollect2','地獄收藏家',D.filter(d=>d.weather==='hell'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length>=2,'獲得兩種地獄骰子',{type:'potion',id:'angel1',amount:1}],
 ['daily5','每日任務達人',(Number(S.dailyQuestCompletions)||0)>=5,'累計完成 5 次每日任務',{type:'coins',amount:5000}]
 ];let changed=false;checks.forEach(([id,name,ok,desc,reward])=>{if(!ok)return;let a=S.achievements[id];if(!a){a={name,desc,reward:rewardText(reward),rewardGiven:false,unlockedAt:new Date().toISOString()};S.achievements[id]=a;changed=true}if(!a.rewardGiven){grantAchievementReward(reward);a.rewardGiven=true;a.reward=rewardText(reward);changed=true;showAchievementPopup({name,desc,reward:a.reward,unlockedAt:a.unlockedAt})}});return changed}
const DAILY_TASKS=[
 {id:'roll25',name:'骰 25 次',kind:'rolls',target:25},
 {id:'roll50',name:'骰 50 次',kind:'rolls',target:50},
 {id:'roll100',name:'骰 100 次',kind:'rolls',target:100},
 {id:'coins3000',name:'獲得 3,000€',kind:'coinsEarned',target:3000},
 {id:'coins5000',name:'獲得 5,000€',kind:'coinsEarned',target:5000},
 {id:'rare2048',name:'獲得 1/2048 或更稀有的骰子一次',kind:'rare',target:1}
];
function dailyTaskIdsForDate(dateKey){let seed=0;for(const ch of String(dateKey))seed=(Math.imul(seed,31)+ch.charCodeAt(0))>>>0;const list=DAILY_TASKS.map(t=>t.id);for(let i=list.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[list[i],list[j]]=[list[j],list[i]];}return list.slice(0,3)}
function ensureDailyQuest(){const today=new Date().toLocaleDateString('en-CA');if(S.questDate!==today){S.questDate=today;S.quest={rolls:0,rare:0,craft:0,coinsEarned:0,rewardClaimed:false,taskIds:dailyTaskIdsForDate(today)};save()}S.quest=S.quest||{rolls:0,rare:0,craft:0,coinsEarned:0,rewardClaimed:false,taskIds:[]};if(!Array.isArray(S.quest.taskIds)||S.quest.taskIds.length!==3||S.quest.taskIds.some(id=>!DAILY_TASKS.some(t=>t.id===id))){S.quest.taskIds=dailyTaskIdsForDate(today);save()}if(typeof S.quest.rewardClaimed!=='boolean')S.quest.rewardClaimed=false;let migrated=false;if(!Number.isFinite(Number(S.dailyQuestCompletions))||Number(S.dailyQuestCompletions)<0){S.dailyQuestCompletions=S.quest.rewardClaimed?1:0;migrated=true}else S.dailyQuestCompletions=Math.floor(Number(S.dailyQuestCompletions)||0);if(Number(S.dailyQuestCompletions)===0&&S.quest.rewardClaimed){S.dailyQuestCompletions=1;migrated=true}if(migrated)save();if(S.quest.rewardClaimed&&Number(S.dailyQuestCompletions)>0)checkAchievements()}
function dailyTaskProgress(task){const current=task.kind==='rolls'?Number(S.quest.rolls)||0:task.kind==='coinsEarned'?Number(S.quest.coinsEarned)||0:Number(S.quest.rare)||0;return Math.min(current,task.target)}
function checkDailyReward(){ensureDailyQuest();if(S.quest.rewardClaimed)return false;const chosen=S.quest.taskIds.map(id=>DAILY_TASKS.find(t=>t.id===id)).filter(Boolean);if(chosen.length!==3||!chosen.every(t=>dailyTaskProgress(t)>=t.target))return false;S.quest.rewardClaimed=true;S.dailyQuestCompletions=(Number(S.dailyQuestCompletions)||0)+1;S.coins=(Number(S.coins)||0)+888;checkAchievements();toast('每日任務全部完成！獲得 888€');save();return true}
function renderQuests(){ensureDailyQuest();checkDailyReward();const tasks=S.quest.taskIds.map(id=>DAILY_TASKS.find(t=>t.id===id)).filter(Boolean).map(t=>({id:t.id,name:t.name,v:dailyTaskProgress(t),m:t.target}));const allDone=tasks.length===3&&tasks.every(t=>t.v>=t.m);document.getElementById('questList').innerHTML=tasks.map(t=>`<div class="recipe"><div style="flex:1"><h3>${t.name}</h3><p>${format(t.v)}/${format(t.m)}</p><div class="bar"><span style="width:${Math.min(100,t.v/t.m*100)}%"></span></div></div><span>${t.v>=t.m?'✓':'…'}</span></div>`).join('')+`<div class="recipe"><div><h3>每日完成獎勵</h3><p>${allDone?'今日任務已全部完成':'完成系統安排的 3 項每日任務即可領取'}</p></div><b>${S.quest.rewardClaimed?'已領取':'+888€'}</b></div>`;const achievementRows=[['roll100','擲骰新手',`累計擲骰 ${compactNum(Math.min(S.rolls,100))}/100 次`,'100€'],['roll1000','命運常客',`累計擲骰 ${compactNum(Math.min(S.rolls,1000))}/1K 次`,'1,000€'],['roll10000','擲骰熟手',`累計擲骰 ${compactNum(Math.min(S.rolls,10000))}/10K 次`,'運氣藥水 II ×2'],['roll100000','命運征服者',`累計擲骰 ${compactNum(Math.min(S.rolls,100000))}/100K 次`,'天堂藥水 I ×1'],['roll200000','別再掛了',`累計擲骰 ${compactNum(Math.min(S.rolls,200000))}/200K 次`,'天堂藥水 I ×1'],['roll400000','不見天日',`累計擲骰 ${compactNum(Math.min(S.rolls,400000))}/400K 次`,'天堂藥水 II ×1'],['collect5','收藏起步',`發現 ${Math.min(totalUnique(),5)}/5 種骰子`,'500€'],['collect12','收藏家',`發現 ${Math.min(totalUnique(),12)}/12 種骰子`,'1,200€'],['collect20','收藏大師',`發現 ${Math.min(totalUnique(),20)}/20 種骰子`,'運氣藥水 III ×1'],['collect28','收藏專家',`發現 ${Math.min(totalUnique(),28)}/28 種骰子`,'運氣藥水 III ×2'],['rare2048','稀有發現者',`最高紀錄：${S.best?'1/'+compactNum(S.best.den):'尚未獲得'}（目標 1/2,048 或更稀有）`,'運氣藥水 II ×1'],['rare1m','百萬分之一',`最高紀錄：${S.best?'1/'+compactNum(S.best.den):'尚未獲得'}（目標 1/1M 或更稀有）`,'運氣藥水 III ×1'],['rare10m','千萬分之一',`最高紀錄：${S.best?'1/'+compactNum(S.best.den):'尚未獲得'}（目標 1/10M 或更稀有）`,'運氣藥水 III ×1'],['craftVoid','虛空',`合成虛空手套`,'速度藥水 I ×1'],['craftUniverse','宇宙',`合成宇宙手套`,'速度藥水 II ×2'],['rainCollect2','雨中收藏家',`已獲得 ${Math.min(D.filter(d=>d.weather==='rain'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length,2)}/2 種雨天骰子`,'8,000€'],['snowCollect2','雪境收藏家',`已獲得 ${Math.min(D.filter(d=>d.weather==='snow'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length,2)}/2 種雪天骰子`,'運氣藥水 III ×1'],['thunderCollect2','雷霆收藏家',`已獲得 ${Math.min(D.filter(d=>d.weather==='thunder'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length,2)}/2 種打雷骰子`,'天堂藥水 I ×1'],['crystalCollect2','水晶收藏家',`已獲得 ${Math.min(D.filter(d=>d.weather==='crystal'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length,2)}/2 種水晶骰子`,'運氣藥水 III ×1'],['hellCollect2','地獄收藏家',`已獲得 ${Math.min(D.filter(d=>d.weather==='hell'&&(S.first?.[d.id]||Number(S.bag?.[d.id])>0)).length,2)}/2 種地獄骰子`,'天堂藥水 I ×1'],['daily5','每日任務達人',`累計完成 ${Math.min(Number(S.dailyQuestCompletions)||0,5)}/5 次每日任務`,'5,000€']];document.getElementById('achievementList').innerHTML=achievementRows.map(([id,name,desc,reward])=>{const unlocked=!!S.achievements[id];return `<div class="recipe achievement-row ${unlocked?'is-done':'is-pending'}"><div><h3>${unlocked?'✓':'◇'} ${name}</h3><p>${desc}</p><p class="mini">獎勵：${reward}</p></div><span>${unlocked?'✓ 已完成':'○ 未完成'}</span></div>`}).join('')}
function renderProfile(){const input=document.getElementById('profileNameInput');if(input&&document.activeElement!==input)input.value=S.name}
const VISITOR_KEY='diceRealmVisitorIdV1';
function getVisitorId(){try{let id=localStorage.getItem(VISITOR_KEY);if(!id){id=(globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():'v-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2));localStorage.setItem(VISITOR_KEY,id)}return id}catch{return 'session-'+Math.random().toString(36).slice(2)+Date.now().toString(36)}}
let visitEventBusy=false,lastVisitEventAt=0;
async function recordGameVisit(eventType='heartbeat'){if(!supabaseClient||visitEventBusy)return;const now=Date.now();if(eventType==='heartbeat'&&now-lastVisitEventAt<240000)return;visitEventBusy=true;try{const userId=currentUser?.id||null;const visitorId='browser:'+getVisitorId();const row={visitor_id:visitorId,user_id:userId,username:userId?String(S.name||'玩家').slice(0,20):null,event_type:eventType,occurred_at:new Date().toISOString()};const {error}=await supabaseClient.from('game_visit_events').insert(row);if(error)throw error;lastVisitEventAt=now}catch(e){console.debug('Visit tracking skipped',e)}finally{visitEventBusy=false}}
function startGameVisitTracking(){recordGameVisit('visit');setInterval(()=>recordGameVisit('heartbeat'),5*60*1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)recordGameVisit('visible')});}

async function adminApi(payload){if(!isAdmin())throw new Error('沒有管理員權限');const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw new Error('登入狀態已失效，請重新登入');const res=await fetch(SUPABASE_URL+'/functions/v1/dice-rng-admin',{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':'Bearer '+session.access_token},body:JSON.stringify(payload)});const data=await res.json().catch(()=>({error:'伺服器回應格式錯誤'}));if(!res.ok)throw new Error((data.error||'管理操作失敗')+'（HTTP '+res.status+'）');return data}
const ADMIN_GRANT_LABELS={coins:'遊戲幣 (€)',luck1:'運氣藥水 I',luck2:'運氣藥水 II',luck3:'運氣藥水 III',angel1:'天堂藥水 I',angel2:'天堂藥水 II'};
