async function loadAdminGrantHistory(){const list=document.getElementById('adminGrantHistoryList'),status=document.getElementById('adminGrantHistoryStatus');if(!isAdmin()){list.innerHTML='<div class="empty">沒有管理員權限。</div>';return}list.innerHTML='<div class="empty">正在讀取雲端發放紀錄…</div>';status.textContent='正在載入…';try{const {data,error}=await supabaseClient.from('admin_actions').select('admin_email,action_type,details,affected_count,created_at').order('created_at',{ascending:false}).limit(300);if(error)throw error;const rows=(data||[]).filter(r=>String(r.action_type||'').startsWith('grant_')).slice(0,200);if(!rows.length){list.innerHTML='<div class="empty">目前沒有發放紀錄。</div>';status.textContent='讀取完成；0 筆紀錄。';return}list.innerHTML=rows.map(r=>{const d=r.details||{},date=r.created_at?new Date(r.created_at).toLocaleString('zh-TW',{hour12:false}):'時間未知';const type=d.type||'',item=type==='coins'?'遊戲幣 (€)':type==='aura'?(D.find(x=>x.id===d.auraId)?.name||d.auraName||d.auraId||'光環／骰子'):type==='potion'?(ADMIN_GRANT_LABELS[d.potionId]||d.potionName||d.potionId||'藥水'):(d.itemName||d.itemId||r.action_type);const target=d.scope==='all'?'全體玩家':(d.username||d.targetUsername||'指定玩家');const amount=(Number(d.amount)||0).toLocaleString('en-US');const detail=d.scope==='all'?`每位 ${amount}；影響 ${Number(r.affected_count)||0} 位`:`數量 ${amount}`;return `<div class="card" style="margin:8px 0;padding:12px"><b>${escapeHTML(date)}</b><div style="margin-top:5px">管理員：${escapeHTML(r.admin_email||'未知')}</div><div>對象：${escapeHTML(target)}</div><div>項目：${escapeHTML(item)}</div><div>數量：${escapeHTML(detail)}</div><div class="mini">紀錄類型：${escapeHTML(r.action_type||'')}</div></div>`}).join('');status.textContent=`已從雲端載入 ${rows.length} 筆發放紀錄（最多顯示最近 200 筆）。`}catch(e){list.innerHTML='<div class="empty">讀取失敗：'+escapeHTML(e.message||'請確認管理員是否有權限讀取 admin_actions')+'</div>';status.textContent='無法讀取雲端發放紀錄。'}}

async function loadAdminDashboard(){if(!isAdmin())return;const players=document.getElementById('adminPlayers'),logs=document.getElementById('adminCraftLogs');try{const data=await adminApi({action:'dashboard'});const playerRows=Array.isArray(data.players)?data.players:[];const target=document.getElementById('adminTargetPlayer'),oldTarget=target.value;target.innerHTML='<option value="">請選擇玩家</option>'+playerRows.map(p=>`<option value="${escapeHTML(p.user_id)}">${escapeHTML(p.username||'玩家')} · ${escapeHTML(p.user_id.slice(0,8))}</option>`).join('');if(playerRows.some(p=>p.user_id===oldTarget))target.value=oldTarget;const weatherTarget=document.getElementById('adminPlayerWeatherTarget');if(weatherTarget){const oldWeatherTarget=weatherTarget.value;weatherTarget.innerHTML='<option value="">請選擇玩家</option>'+playerRows.map(p=>`<option value="${escapeHTML(p.user_id)}">${escapeHTML(p.username||'玩家')} · ${escapeHTML(p.user_id.slice(0,8))}</option>`).join('');if(playerRows.some(p=>p.user_id===oldWeatherTarget))weatherTarget.value=oldWeatherTarget;}const banTarget=document.getElementById('adminBanTarget'),oldBanTarget=banTarget.value;banTarget.innerHTML='<option value="">請選擇玩家</option>'+playerRows.map(p=>`<option value="${escapeHTML(p.user_id)}">${escapeHTML(p.username||'玩家')} · ${escapeHTML(p.user_id.slice(0,8))}${p.banned?' · 已停權':''}</option>`).join('');if(playerRows.some(p=>p.user_id===oldBanTarget))banTarget.value=oldBanTarget;const deleteTarget=document.getElementById('adminDeleteTarget'),oldDeleteTarget=deleteTarget.value;deleteTarget.innerHTML='<option value="">請選擇玩家</option>'+playerRows.map(p=>`<option value="${escapeHTML(p.user_id)}">${escapeHTML(p.username||'玩家')} · ${escapeHTML(p.user_id.slice(0,8))}</option>`).join('');if(playerRows.some(p=>p.user_id===oldDeleteTarget))deleteTarget.value=oldDeleteTarget;document.getElementById('adminPlayerCount').textContent=format(playerRows.length);document.getElementById('adminOnlineCount').textContent=format(data.onlineCount);const usernameCounts={};playerRows.forEach(p=>{const key=String(p.username||'玩家').trim().toLocaleLowerCase();usernameCounts[key]=(usernameCounts[key]||0)+1});const numberedPlayers=[...playerRows].sort((a,b)=>{const ta=Date.parse(a.created_at||a.joined_at||a.joined||'')||Number.MAX_SAFE_INTEGER,tb=Date.parse(b.created_at||b.joined_at||b.joined||'')||Number.MAX_SAFE_INTEGER;return ta-tb||String(a.user_id||'').localeCompare(String(b.user_id||''))});const playerNumbers=new Map(numberedPlayers.map((p,i)=>[p.user_id,String(i+1).padStart(5,'0')]));players.innerHTML=playerRows.map(p=>{const playerName=String(p.username||'玩家'),duplicate=(usernameCounts[playerName.trim().toLocaleLowerCase()]||0)>1,number=playerNumbers.get(p.user_id)||'00000';return `<div class="admin-player"><div style="min-width:0"><b>${escapeHTML(playerName)}</b><div class="mini" style="color:#a8b7ff;font-weight:800">#${number}</div>${duplicate?`<div class="mini">同名帳號識別碼：${escapeHTML(String(p.user_id||'').slice(0,8))}</div>`:''}<div class="mini">擲骰 ${format(p.total_rolls||0)} 次 · 骰子 ${format(p.unique_dice||0)} 種 · ${format(p.coins||0)}€</div><div class="mini">最後活動：${p.last_seen?new Date(p.last_seen).toLocaleString():'尚無紀錄'}</div></div><span class="pill ${p.online?'admin-online':'admin-offline'}">${p.online?'● 在線':'○ 離線'}</span></div>`}).join('')||'<div class="empty">尚無玩家資料</div>';const newPlayersBox=document.getElementById('adminNewPlayersList');if(newPlayersBox){const newest=[...numberedPlayers].reverse();newPlayersBox.innerHTML=newest.slice(0,100).map(p=>{const joined=p.created_at||p.joined_at||p.joined;return `<div class="admin-log"><div><b>${escapeHTML(p.username||'玩家')}</b><div class="mini" style="color:#a8b7ff;font-weight:800">#${playerNumbers.get(p.user_id)||'00000'}</div><div class="mini">加入時間：${joined?new Date(joined).toLocaleString():'後端未提供加入時間'}</div><div class="mini">帳號識別碼：${escapeHTML(String(p.user_id||'').slice(0,8))}</div></div><span class="pill">新加入</span></div>`}).join('')||'<div class="empty">尚無玩家資料</div>'}logs.innerHTML=data.crafts.map(x=>`<div class="admin-log"><div><b>${escapeHTML(x.username||'玩家')} · ${escapeHTML(x.item_name||x.item_id)}</b><div class="mini">${x.item_type==='potion'?'藥水合成':'手套合成'} · ${new Date(x.created_at).toLocaleString()}</div></div><span class="pill">#${x.id}</span></div>`).join('')||'<div class="empty">目前沒有合成紀錄</div>'}catch(e){players.innerHTML=logs.innerHTML=`<div class="empty">${escapeHTML(e.message||'載入失敗')}</div>`;document.getElementById('adminTargetPlayer').innerHTML='<option value="">玩家名單載入失敗</option>';document.getElementById('adminBanTarget').innerHTML='<option value="">玩家名單載入失敗</option>'}}
async function loadAdminRareRolls(){if(!isAdmin())return;const box=document.getElementById('adminRareRollLogs');if(!box)return;box.innerHTML='<div class="empty">正在載入稀有擲骰紀錄…</div>';try{let records=[];let apiError=null;try{const data=await adminApi({action:'rare_rolls'});records=Array.isArray(data.records)?data.records:[]}catch(e){apiError=e}try{const {data:rows,error}=await supabaseClient.from('roll_announcements').select('user_id,username,dice_name,den,created_at').gte('den',4096).order('created_at',{ascending:false}).limit(200);if(error)throw error;const merged=new Map();[...records,...(rows||[])].forEach(x=>{const key=[x.user_id,x.dice_name,x.den,x.created_at].join('|');if(!merged.has(key))merged.set(key,x)});records=[...merged.values()].sort((a,b)=>(Date.parse(b.created_at)||0)-(Date.parse(a.created_at)||0)).slice(0,200)}catch(tableError){if(!records.length)throw new Error('讀取紀錄失敗：'+(tableError.message||apiError?.message||'請確認 roll_announcements 資料表及管理員讀取權限'))}const bands=[{label:'1/4,096–1/9,999',min:4096,max:9999},{label:'1/10,000–1/99,999',min:10000,max:99999},{label:'1/100,000–1/999,999',min:100000,max:999999},{label:'1/1,000,000–1/9,999,999',min:1000000,max:9999999},{label:'1/10,000,000 以上',min:10000000,max:Infinity}];const intervalSummary='<div class="admin-log" style="display:block;margin-bottom:10px"><b>最近紀錄的機率區間統計（最多 200 筆）</b><div class="mini" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px">'+bands.map(b=>'<span class="pill">'+b.label+'：'+records.filter(x=>Number(x.den)>=b.min&&Number(x.den)<=b.max).length+' 筆</span>').join('')+'</div></div>';box.innerHTML=intervalSummary+records.map(x=>`<div class="admin-log"><div><b>${escapeHTML(x.username||'玩家')} · ${escapeHTML(x.dice_name||'稀有骰子')}</b><div class="mini">1/${format(x.den)} · 玩家 ID ${escapeHTML(String(x.user_id||'').slice(0,8))} · ${x.created_at?new Date(x.created_at).toLocaleString():'時間未提供'}</div></div><span class="pill">1/${format(x.den)}</span></div>`).join('')||'<div class="empty">目前沒有 1/4096 或更稀有的擲骰紀錄。若玩家曾離線、資料表寫入失敗或後端權限拒絕，過去未寫入的紀錄無法自動補回；必須從既有雲端備份或伺服器日誌恢復，不能憑空重建。</div>'}catch(e){box.innerHTML=`<div class="empty">載入失敗：${escapeHTML(e.message||'未知錯誤')}</div>`}}
document.getElementById('adminNewPlayersRefresh')?.addEventListener('click',loadAdminDashboard);document.getElementById('adminNewPlayersFold')?.addEventListener('toggle',e=>{if(e.target.open)loadAdminDashboard()});
document.getElementById('adminRareRollRefresh')?.addEventListener('click',loadAdminRareRolls);
