document.getElementById('sellSelectedDiceBtn').addEventListener('click',()=>{const grid=document.getElementById('inventoryGrid');if(!inventorySellMode){inventorySellMode=true;grid.classList.add('sell-select-mode');updateInventorySelectedCount();toast('請點選要出售的單顆骰子');return}const checked=[...grid.querySelectorAll('input[data-sell-select]:checked')];if(!checked.length){inventorySellMode=false;grid.classList.remove('sell-select-mode');updateInventorySelectedCount();return}const counts=new Map();for(const cb of checked)counts.set(cb.dataset.sellSelect,(counts.get(cb.dataset.sellSelect)||0)+1);const total=checked.length;const summary=[...counts.entries()].map(([id,count])=>{const d=byId(id);return d?`${d.name} ×${count}`:null}).filter(Boolean).join('、');if(!window.confirm(`你即將出售 ${format(total)} 顆骰子：\n${summary}\n\n此舉動不可復原，確定要出售嗎？`))return;let earned=0;for(const [id,amount] of counts){const d=byId(id);if(!d)continue;const have=Number(S.bag[id])||0;const actual=Math.min(have,amount);if(actual<=0)continue;S.bag[id]=have-actual;if(S.bag[id]<=0)delete S.bag[id];earned+=d.den*actual}S.coins=(Number(S.coins)||0)+earned;S.quest=S.quest||{};S.quest.coinsEarned=(Number(S.quest.coinsEarned)||0)+earned;checkDailyReward();inventorySellMode=false;grid.classList.remove('sell-select-mode');save();render();toast(`已出售 ${format(total)} 顆骰子 +${format(earned)}€`)});

function render(){updateWeatherUI();if(checkAchievements())save();const tenthCount=((Number(S.rolls)||0)%10);const rollsLeft=10-tenthCount;const tenthProgress=document.getElementById('tenthProgress');if(tenthProgress){tenthProgress.classList.toggle('ready',rollsLeft===1);document.getElementById('tenthProgressLabel').textContent=rollsLeft===1?'下一抽雙倍運氣！':`再擲 ${rollsLeft} 次`;document.getElementById('tenthProgressBar').style.width=(tenthCount*10)+'%';}document.getElementById('playerName').textContent=S.name;document.getElementById('avatar').textContent=(S.name||'旅').slice(0,1);document.getElementById('totalRolls').textContent=format(S.rolls);document.getElementById('uniqueCount').textContent=totalUnique()+' / '+D.length;document.getElementById('luckStat').textContent='+'+luck()+'%';document.getElementById('coinBalance').textContent=format(Number(S.coins)||0)+'€';document.getElementById('bagTotal').textContent=totalDice()+' / '+(Number(S.bagCapacity)||35);document.getElementById('bagCapacity').textContent=totalDice()+' / '+(Number(S.bagCapacity)||35)+' 顆';renderAutoDepositOptions();document.getElementById('rollBtn').disabled=rolling||totalDice()>=(Number(S.bagCapacity)||35);document.getElementById('autoBtn').disabled=totalDice()>=(Number(S.bagCapacity)||35)||!!autoTimer;const cap=Number(S.bagCapacity)||35,up=document.getElementById('upgradeBagBtn');up.disabled=cap>=200||Number(S.coins)<bagUpgradeCost(cap);up.textContent=cap>=200?'已達上限':'擴充 +1 · '+format(bagUpgradeCost(cap))+'€';document.getElementById('bagUpgradeInfo').textContent=cap>=200?'容量 '+cap+'/200，已達上限':`容量 ${cap}/200 · 下次擴充 ${format(bagUpgradeCost(cap))}€`;const autoWeatherBtn=document.getElementById('autoDepositWeatherBtn');if(autoWeatherBtn){autoWeatherBtn.textContent='自動添加：'+(S.autoDepositWeatherEnabled?'開啟':'關閉');autoWeatherBtn.setAttribute('aria-pressed',S.autoDepositWeatherEnabled?'true':'false');autoWeatherBtn.classList.toggle('primary',!!S.autoDepositWeatherEnabled);}renderAutoSellOptions();renderInventory();renderCodex();renderGloves();renderPotions();renderQuests();renderProfile();}
function bagUpgradeCost(currentCapacity){const next=currentCapacity+1;if(next>=100)return next*100;return next<=39?1000:1000+(next-39)*250}
document.getElementById('upgradeBagBtn').onclick=()=>{const cap=Number(S.bagCapacity)||35;if(cap>=200){toast('背包已達目前上限 200 顆');return}const cost=bagUpgradeCost(cap);if((Number(S.coins)||0)<cost){toast(`€ 不足，擴充需要 ${format(cost)}€`);return}S.coins-=cost;S.bagCapacity=cap+1;save();render();toast(`背包容量已擴充至 ${S.bagCapacity} 顆`)};
