function stopAuto(){if(autoTimer)clearInterval(autoTimer);autoTimer=null;document.getElementById('autoBtn').classList.remove('roll-progress');document.getElementById('autoBtn').disabled=false;document.getElementById('stopBtn').disabled=true}
function restartAutoInterval(){if(!autoTimer)return;clearInterval(autoTimer);autoTimer=setInterval(()=>{if(totalDice()>=(Number(S.bagCapacity)||35)){stopAuto();go('inventory');toast('背包已滿，自動擲骰停止');return}if(!rolling)doRoll()},Math.max(900,950/(1+speed()/100)))}
document.getElementById('autoBtn').onclick=()=>{if(autoTimer||totalDice()>=(Number(S.bagCapacity)||35)){if(totalDice()>=(Number(S.bagCapacity)||35))go('inventory');return}document.getElementById('autoBtn').disabled=true;document.getElementById('stopBtn').disabled=false;autoTimer=setInterval(()=>{if(totalDice()>=(Number(S.bagCapacity)||35)){stopAuto();go('inventory');toast('背包已滿，自動擲骰停止');return}if(!rolling)doRoll()},Math.max(900,950/(1+speed()/100)));toast('自動擲骰已開始')};
document.getElementById('stopBtn').onclick=stopAuto;
