document.getElementById('saveName').onclick=async()=>{let n=document.getElementById('profileNameInput').value.trim().slice(0,20);if(!n){toast('名稱不可空白');return}if(!currentUser||!supabaseClient){toast('請先登入再更改名稱');return}const btn=document.getElementById('saveName');btn.disabled=true;try{const {data:profiles,error}=await supabaseClient.from('player_profiles').select('user_id,username').limit(5000);if(error)throw error;const key=n.normalize('NFKC').trim().toLocaleLowerCase();if((profiles||[]).some(p=>p.user_id!==currentUser.id&&String(p.username||'').normalize('NFKC').trim().toLocaleLowerCase()===key)){document.getElementById('accountActionMessage').textContent='玩家名稱重複';toast('玩家名稱重複');return}const now=new Date().toISOString();const {error:profileError}=await supabaseClient.from('player_profiles').upsert({user_id:currentUser.id,username:n,total_rolls:Number(S.rolls)||0,unique_dice:totalUnique(),rarest_den:Number(S.best?.den)||0,coins:Number(S.coins)||0,...achievementStats(),last_seen:now,updated_at:now},{onConflict:'user_id'});if(profileError)throw profileError;S.name=n;save();render();await syncCloudSave();document.getElementById('accountActionMessage').textContent='名稱已更新';toast('名稱已更新')}catch(e){const message=String(e.message||'請稍後重試');document.getElementById('accountActionMessage').textContent=message.includes('玩家名稱重複')?'玩家名稱重複':'更改名稱失敗';toast(message.includes('玩家名稱重複')?'玩家名稱重複':'更改名稱失敗：'+message)}finally{btn.disabled=false}};
document.getElementById('resetBtn').onclick=async()=>{const msg=document.getElementById('accountActionMessage');if(!confirm('第一次確認：確定要刪除目前帳號及遊戲進度嗎？'))return;if(!confirm('第二次確認：這會永久刪除帳號資料，成功後將無法登入，且會從排行榜移除。確定刪除？'))return;if(!currentUser||!supabaseClient){msg.textContent='目前沒有登入雲端帳號。若要刪除本機試玩資料，請先登入帳號；此按鈕不會只清空資料來假裝刪除帳號。';return}const btn=document.getElementById('resetBtn');btn.disabled=true;msg.textContent='正在請求伺服器刪除帳號與相關資料…';try{const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw new Error('登入狀態已失效，請重新登入');const res=await fetch(SUPABASE_URL+'/functions/v1/dice-rng-admin',{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':'Bearer '+session.access_token},body:JSON.stringify({action:'delete_self_account',confirmTwice:true})});const result=await res.json().catch(()=>({error:'伺服器回應格式錯誤'}));if(!res.ok||result.success===false||result.error)throw new Error(result.error||'伺服器尚未支援自助刪除帳號');if(result.deleted!==true)throw new Error('伺服器沒有確認帳號已刪除，為保護資料，本機不會清空存檔。請先在 dice-rng-admin 後端實作 delete_self_account。');stopAuto();localStorage.removeItem(KEY);await supabaseClient.auth.signOut();currentUser=null;S=fresh();localStorage.setItem(KEY,JSON.stringify(S));render();msg.textContent='帳號已由伺服器刪除，並已登出。';toast('帳號刪除完成');await refreshLeaderboards()}catch(e){msg.textContent='刪除失敗：'+(e.message||'請確認管理後端是否支援自助刪除帳號');toast(msg.textContent)}finally{btn.disabled=false}};document.getElementById('profileLogoutBtn')?.addEventListener('click',async()=>{if(!currentUser){toast('目前沒有登入雲端帳號');return}const {error}=await supabaseClient.auth.signOut();if(error){toast('登出失敗：'+error.message);return}toast('已登出雲端帳號')});
