// 修正出售視窗在原始腳本執行時尚未載入，導致按鈕沒有事件的問題。
(function(){
 function ready(fn){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fn,{once:true});else fn()}
 ready(function(){
  const $=id=>document.getElementById(id);
  const values={common:100,rare:1000,legendary:10000,mythic:50000,secret:100000};
  const order={common:0,rare:1,legendary:2,mythic:3,secret:4};
  function listPets(){return Array.isArray(S.pets)?S.pets:[]}
  function rarityOf(item){return petById(item&&item.id)?.rarity||'common'}
  function renderChoices(){const list=$('petSellChoices');if(!list)return;const pets=[...listPets()].sort((a,b)=>(order[rarityOf(a)]??99)-(order[rarityOf(b)]??99));list.innerHTML=pets.map(item=>{const p=petById(item.id);if(!p)return '';const rarity=rarityOf(item),price=values[rarity]||100;return `<label class="pet-sell-choice"><input type="checkbox" class="pet-sell-check" value="${escapeHTML(item.uid)}"><span class="pet-sell-choice-art">${petArt(p,true)}</span><span class="pet-sell-choice-info"><b class="${petRarity(rarity).cls}">${escapeHTML(p.name)}</b><small>${petRarity(rarity).name} · 出售可得 ${price.toLocaleString('en-US')}€</small></span></label>`}).join('')||'<div class="empty">目前沒有可出售的寵物。</div>';updateSummary()}
  function updateSummary(){const summary=$('petSellSummary'),confirmBtn=$('petSellConfirmBtn');if(!summary)return;const ids=[...document.querySelectorAll('#petSellChoices .pet-sell-check:checked')].map(x=>x.value);let total=0;for(const uid of ids){const item=listPets().find(x=>String(x.uid)===uid);if(item)total+=values[rarityOf(item)]||100}summary.textContent=`已選擇 ${ids.length} 隻寵物，合計可獲得 ${total.toLocaleString('en-US')}€。`;if(confirmBtn)confirmBtn.disabled=ids.length===0}
  function open(){const modal=$('petSellModal');if(!modal)return;renderChoices();modal.hidden=false;modal.style.display='flex';document.body.classList.add('pet-sell-open')}
  function close(){const modal=$('petSellModal');if(modal){modal.hidden=true;modal.style.display='none'}document.body.classList.remove('pet-sell-open')}
  // Capture click ensures this working handler wins over any stale listener registered earlier.
  document.addEventListener('click',function(e){
   const target=e.target;
   if(target.closest('#petSellBtn')){e.preventDefault();e.stopImmediatePropagation();open();return}
   if(target.closest('#petSellCancelBtn')||target.closest('#petSellCancelBtnBottom')){e.preventDefault();e.stopImmediatePropagation();close();return}
   if(target.closest('#petSellSelectAllBtn')){e.preventDefault();e.stopImmediatePropagation();document.querySelectorAll('#petSellChoices .pet-sell-check').forEach(x=>x.checked=true);updateSummary();return}
   if(target.closest('#petSellClearBtn')){e.preventDefault();e.stopImmediatePropagation();document.querySelectorAll('#petSellChoices .pet-sell-check').forEach(x=>x.checked=false);updateSummary();return}
   if(target.closest('#petSellConfirmBtn')){e.preventDefault();e.stopImmediatePropagation();const ids=[...document.querySelectorAll('#petSellChoices .pet-sell-check:checked')].map(x=>x.value);if(!ids.length){if(typeof toast==='function')toast('請先選擇要出售的寵物');return}const chosen=listPets().filter(x=>ids.includes(String(x.uid)));let total=0;chosen.forEach(x=>total+=values[rarityOf(x)]||100);if(!chosen.length)return;if(!window.confirm(`確定出售選取的 ${chosen.length} 隻寵物，總共獲得 ${total.toLocaleString('en-US')}€？此操作無法復原。`))return;S.pets=listPets().filter(x=>!ids.includes(String(x.uid)));S.equippedPetUids=(S.equippedPetUids||[]).filter(uid=>!ids.includes(String(uid)));S.coins=(Number(S.coins)||0)+total;save();close();if(typeof render==='function')render();if(typeof renderPetsPage==='function')renderPetsPage();if(typeof toast==='function')toast(`已出售 ${chosen.length} 隻寵物，獲得 +${total.toLocaleString('en-US')}€`);return}
   if(target.id==='petSellModal'){close()}
  },true);
  document.addEventListener('change',function(e){if(e.target.matches('#petSellChoices .pet-sell-check'))updateSummary()},true);
  // If the existing modal is present, keep it hidden until the user taps the single sell button.
  const modal=$('petSellModal');if(modal){modal.hidden=true;modal.style.display='none'}
 });
})();
